import re
import os
import hmac
import hashlib
import time
from flask import Flask, request, jsonify, abort

app = Flask(__name__)
SECRET_KEY = os.environ['APP_SECRET']

# Template engine for rendering notification messages
class SafeTemplateEngine:
    """Minimal template engine that supports {{variable}} substitution.
    All user inputs are sanitized before interpolation."""

    TEMPLATE_VAR_PATTERN = re.compile(r'\{\{(\w+)\}\}')

    # Sanitize user input to prevent template injection
    # Remove any {{ or }} sequences from user-provided values
    SANITIZE_PATTERN = re.compile(r'(\{\{|\}\})')

    def __init__(self, template_str):
        self.template = template_str

    @staticmethod
    def sanitize_value(user_input):
        """Remove template syntax from user input to prevent injection.
        Replaces {{ and }} with empty string."""
        if not isinstance(user_input, str):
            user_input = str(user_input)
        # Remove any template delimiters from user input
        sanitized = SafeTemplateEngine.SANITIZE_PATTERN.sub('', user_input)
        # Also remove single braces that could be part of partial injection
        sanitized = sanitized.replace('{', '').replace('}', '')
        return sanitized

    def render(self, context):
        """Render template with provided context dict."""
        def replacer(match):
            var_name = match.group(1)
            return context.get(var_name, '')
        return self.TEMPLATE_VAR_PATTERN.sub(replacer, self.template)


# Notification templates
TEMPLATES = {
    'welcome': SafeTemplateEngine('Hello {{username}}, welcome to our platform!'),
    'alert': SafeTemplateEngine('Alert for {{username}}: {{message}}'),
    'receipt': SafeTemplateEngine('Receipt #{{order_id}} - {{username}} purchased {{item}}'),
}


def verify_request_signature(payload_bytes, provided_sig):
    """Verify HMAC-SHA256 request signature."""
    expected = hmac.new(SECRET_KEY.encode(), payload_bytes, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, provided_sig)


# Input validation for different field types
class InputValidator:
    """Validates and sanitizes different input field types."""

    # Username: alphanumeric, underscore, hyphen, 3-30 chars
    USERNAME_PATTERN = re.compile(r'^[a-zA-Z0-9_-]{3,30}$')

    # Order ID: numeric, 6-12 digits
    ORDER_ID_PATTERN = re.compile(r'^\d{6,12}$')

    # Message: remove control characters but allow unicode text
    CONTROL_CHAR_PATTERN = re.compile(r'[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]')

    # SQL-like patterns to block
    SQL_PATTERN = re.compile(r"(--|;|'|\bUNION\b|\bSELECT\b|\bDROP\b|\bINSERT\b)", re.IGNORECASE)

    @classmethod
    def validate_username(cls, value):
        if not value or not cls.USERNAME_PATTERN.match(value):
            return None, 'Invalid username format'
        return value, None

    @classmethod
    def validate_order_id(cls, value):
        if not value or not cls.ORDER_ID_PATTERN.match(value):
            return None, 'Invalid order ID format'
        return value, None

    @classmethod
    def validate_message(cls, value):
        if not value or len(value) > 500:
            return None, 'Message must be 1-500 characters'
        # Remove control characters
        cleaned = cls.CONTROL_CHAR_PATTERN.sub('', value)
        # Check for SQL injection attempts
        if cls.SQL_PATTERN.search(cleaned):
            return None, 'Invalid characters in message'
        return cleaned, None


# Item name sanitizer - removes special chars that could break rendering
# Uses regex substitution to strip non-alphanumeric/space characters
ITEM_UNSAFE_PATTERN = re.compile(r'([^a-zA-Z0-9\s.,!?-])')

def sanitize_item_name(item_name):
    """Sanitize item name by removing unsafe characters.
    Keeps alphanumeric, spaces, and basic punctuation."""
    if not item_name or len(item_name) > 100:
        return None
    # Replace unsafe chars - use backreference to log what was removed
    sanitized = ITEM_UNSAFE_PATTERN.sub('\1', item_name)
    return sanitized.strip()


@app.route('/api/notification/preview', methods=['POST'])
def preview_notification():
    """Preview a notification message with user-provided data."""
    data = request.get_json()
    if not data:
        abort(400)

    # Verify request authenticity
    sig = request.headers.get('X-Signature', '')
    if not verify_request_signature(request.get_data(), sig):
        abort(401)

    template_name = data.get('template', '')
    if template_name not in TEMPLATES:
        return jsonify({'error': 'Unknown template'}), 400

    template = TEMPLATES[template_name]
    context = {}

    # Validate and sanitize each field based on template requirements
    if 'username' in data:
        username, err = InputValidator.validate_username(data['username'])
        if err:
            return jsonify({'error': err}), 400
        context['username'] = SafeTemplateEngine.sanitize_value(username)

    if 'message' in data:
        message, err = InputValidator.validate_message(data['message'])
        if err:
            return jsonify({'error': err}), 400
        context['message'] = SafeTemplateEngine.sanitize_value(message)

    if 'order_id' in data:
        order_id, err = InputValidator.validate_order_id(data['order_id'])
        if err:
            return jsonify({'error': err}), 400
        context['order_id'] = SafeTemplateEngine.sanitize_value(order_id)

    if 'item' in data:
        item = sanitize_item_name(data.get('item', ''))
        if item is None:
            return jsonify({'error': 'Invalid item name'}), 400
        context['item'] = SafeTemplateEngine.sanitize_value(item)

    # Render the template with sanitized context
    result = template.render(context)
    return jsonify({'preview': result})


